import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';
import { hundredths } from '../rates/useRates';

/** A pool's member as the server sends it: the person (or, for a member that is another pool, null
 *  and that pool's name in `pool`), their share (two decimals) and whether they are retired (a
 *  retirement date set, whatever the date), and their cut of the pool's pot (two decimals; null when
 *  the pool is unbalanced or has no pot). A pool that is a member of none has the sheet's pot; one
 *  that is a member of another has its cut there. */
export type PoolMember = {
  personId: number | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string | null;
  pool: string | null;
};

/** A pool as the server sends it: its name, its members in the order added, the total of their
 *  shares (two decimals; a retired member's counts 0.00) and whether it is exactly 100.00. */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

/** A share percent: up to two decimals. */
export const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

export const poolsKey = (sheet: string) => ['sheet', sheet, 'pools'] as const;

/** The sheet's pools, in the order added, re-read whenever the sheet is loaded. */
export function usePools(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(poolsKey(sheet), asOf),
    queryFn: () => getJson<Pool[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/pools`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The cuts of the person members of `pools` (just `personId`'s when given) added up, in cents; a
 *  pool member that is another pool, or a member with no cut, adds nothing. */
export function cutTotalCents(pools: Pool[], personId?: number): bigint {
  return pools
    .flatMap((p) => p.members)
    .filter((m) => m.personId !== null && m.cut !== null && (personId === undefined || m.personId === personId))
    .reduce((sum, m) => sum + hundredths(m.cut as string), 0n);
}
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import type { Person } from '../people/usePeople';
import { showDue } from '../rates/useRates';
import { cutTotalCents, usePools } from './usePools';

/** A person's cut total: their cuts across every pool they are a member of, added up (a pool that
 *  shows no cuts adds nothing). */
function PersonCutTotal({ sheet, person }: { user: string; sheet: string; person: Person }) {
  const { data: pools = [] } = usePools(sheet);
  return <td data-testid="person-cut-total">{showDue(cutTotalCents(pools, person.id))}</td>;
}

/** The sheet's cut total: everyone's cut total added up. */
function SheetCutTotal({ sheet }: { user: string; sheet: string }) {
  const { data: pools = [] } = usePools(sheet);
  return (
    <p>
      Cuts in total: <strong data-testid="rollup-cut-total">{showDue(cutTotalCents(pools))}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 13, Component: () => <th>Cut total</th> }),
  PersonCells.fill({ order: 13, Component: PersonCutTotal }),
  SheetPanels.fill({ order: 20.5, Component: SheetCutTotal }),
];

